// Operators at a training (docs/spec/operators.md 干员-1…干员-7): an operator's training data, generated by @aue/data
// into data/operators/<id>.json, and a build — elite, level, potential, trust, skill and skill level, module and module
// level — as @aue/sim's operator. The data is loaded per operator, on first use.
import index from '../data/operators/index.json' with { type: 'json' };
import { withTrait } from './traits.js';
import { skillDefOf } from './skills.js';
import { unlockedAt, talentsAt, alwaysOnBb, teamPart, rangePart, critPart, timedPart, deployPart } from './talents.js';

/** @typedef {import('@aue/sim').OperatorDef} OperatorDef */
/**
 * A training (干员-1, 干员-2, 干员-7): elite phase 0–2, level, potential 1–6, trust 0–200 (%), the skill slot (0-based;
 * −1 for none) and its level 1–10 (8–10: 专精 1–3), the module (0-based; −1 or left out for none) and its level 1–3.
 * @typedef {{ elite: number, level: number, potential: number, trust: number, skill: number, skillLevel: number, module?: number, moduleLevel?: number }} Build
 */
/** @typedef {Record<string, number>} Stats */
/**
 * An operator's training data (干员-1…干员-5), as @aue/data writes it.
 * @typedef {{ name: string, position: 'MELEE' | 'RANGED', profession: string, branch: string, powers: string[], rarity: number,
 *   phases: { maxLevel: number, range: { row: number, col: number }[], frames: { level: number, stats: Stats }[] }[],
 *   favor: { level: number, stats: Stats } | null, potentials: Stats[],
 *   skills: { id: string, phase: number, levels: import('./skills.js').SkillLevel[] }[],
 *   traits: { phase: number, level: number, potential: number, bb: Stats }[], talents: TalentCandidate[][], modules: Module[] }} Training
 */
/**
 * A talent candidate (干员-4): unlock, name and description (null for a hidden one), range id, numeric and text blackboard.
 * @typedef {{ phase: number, level: number, potential: number, name: string | null, description: string | null, rangeId: string | null,
 *   bb: Stats, text?: Record<string, string>, hidden: boolean, token: string | null }} TalentCandidate
 */
/**
 * A module (干员-5): its levels with the attribute additions (the operator's and each token's), and the parts.
 * @typedef {{ id: string, name: string, type: string, phase: number, level: number,
 *   levels: { level: number, stats: Stats, tokens: Record<string, Stats>, parts: ModulePart[] }[] }} Module
 */
/**
 * @typedef {{ target: string, token: boolean, gameTag: string | null, mapTag: string | null,
 *   trait: { phase: number, level: number, potential: number, add: string | null, override: string | null, rangeId: string | null, bb: Stats, text?: Record<string, string> }[],
 *   talents: { index: number, phase: number, level: number, potential: number, name: string | null, upgrade: string | null, rangeId: string | null,
 *     bb: Stats, text?: Record<string, string>, hidden: boolean, modes: number[] | null }[] }} ModulePart
 */

/** Every operator there is training data for, by id: name, rarity, profession, branch. */
export const ROSTER = /** @type {Readonly<Record<string, { name: string, rarity: number, profession: string, branch: string }>>} */ (index.operators);
/** Where the training data comes from: the ArknightsGameData commit. */
export const rosterSource = index.source;

/** An operator's training data (干员-1), loaded on first use. @param {string} id @returns {Promise<Training>} */
export async function loadTraining(id) {
  if (!Object.hasOwn(ROSTER, id)) throw new RangeError(`no operator ${id}`);
  return (await import(`../data/operators/${id}.json`, { with: { type: 'json' } })).default;
}

/** @param {number} v @param {number} lo @param {number} hi */
const clamp = (v, lo, hi) => Math.min(hi, Math.max(lo, v));

/**
 * The keyframes' attributes at a level (干员-1): linear between the two around it, not rounded.
 * @param {{ level: number, stats: Stats }[]} frames @param {number} level @returns {Stats}
 */
function atLevel(frames, level) {
  const i = Math.max(0, frames.findIndex((f) => f.level >= level) - 1), a = frames[i], b = frames[Math.min(i + 1, frames.length - 1)];
  const t = b.level === a.level ? 0 : (level - a.level) / (b.level - a.level);
  return Object.fromEntries(Object.keys(a.stats).map((k) => [k, a.stats[k] + (b.stats[k] - a.stats[k]) * t]));
}

/** @typedef {Module['levels'][number]} ModuleLevel */

/**
 * The attributes at a training (干员-1, 干员-7): elite and level, then trust, then potential, then the module level's.
 * @param {Training} t @param {Build} b @param {ModuleLevel | null} mod @returns {Stats}
 */
export function statsAt(t, b, mod) {
  const phase = t.phases[b.elite], out = atLevel(phase.frames, clamp(b.level, 1, phase.maxLevel));
  if (t.favor) {
    const share = clamp(b.trust, 0, 100) / 100;
    for (const [k, v] of Object.entries(t.favor.stats)) out[k] += v * share;
  }
  for (const p of [...t.potentials.slice(0, clamp(b.potential, 1, 6) - 1), mod?.stats ?? {}]) for (const [k, v] of Object.entries(p)) out[k] = (out[k] ?? 0) + v;
  return out;
}

/**
 * The module level a training equips (干员-7), or null for none: the build's module at its level, capped at its last.
 * Throws for a module the operator does not have or has not unlocked (its elite phase and level).
 * @param {Training} t @param {Build} b @returns {ModuleLevel | null}
 */
export function moduleAt(t, b) {
  const i = b.module ?? -1, m = t.modules[i];
  if (i < 0) return null;
  if (!m || !unlockedAt({ ...m, potential: 0 }, b)) throw new RangeError(`${t.name}: module ${i} is not unlocked at elite ${b.elite} level ${b.level}`);
  return m.levels[clamp(b.moduleLevel ?? 1, 1, m.levels.length) - 1];
}

/**
 * The talents at a training (干员-6, 干员-7): each talent's own candidate, or the module's upgrade of it — the last
 * unlocked candidate of the level's talent parts (not a token's, valid in every mode and map) for that talent, its
 * upgrade text as the description.
 * @param {Training} t @param {Build} b @param {ModuleLevel | null} mod @returns {import('./talents.js').Talent[]}
 */
function upgradedTalents(t, b, mod) {
  /** @type {(import('./talents.js').Talent | null)[]} */
  const out = talentsAt(t, b);
  for (const p of mod?.parts ?? []) {
    if (!p.target.startsWith('TALENT') || p.token || p.gameTag || p.mapTag) continue;
    for (const c of p.talents) if (c.index >= 0 && unlockedAt(c, b)) out[c.index] = { description: c.upgrade, bb: c.bb, hidden: c.hidden };
  }
  return out.filter((c) => c !== null);
}

/** The trait blackboard at a training (干员-3): the last candidate unlocked. @param {Training} t @param {Build} b */
export function traitAt(t, b) {
  return t.traits.filter((c) => unlockedAt(c, b)).at(-1)?.bb ?? {};
}

/**
 * The team parts of a training's talents (干员-9), with its module's upgrades: those for the deck and those on the field.
 * @param {Training} t @param {Build} b
 */
export function teamTalentsAt(t, b) {
  const parts = upgradedTalents(t, b, moduleAt(t, b)).map(teamPart).filter((p) => p !== null);
  return { deck: parts.filter((p) => p.when === 'deck'), field: parts.filter((p) => p.when === 'field').map(({ when, ...rest }) => rest) };
}

/**
 * The talent fields of an operator record (干员-6, 干员-9, 干员-11…干员-14): the always-on part's 部署费用 and 再部署时间
 * to fold in and the rest as `talentBb`, the on-field team talents, the in-range, chance, timed and deployment talents — each only
 * when there is one.
 * @param {Training} t @param {Build} b @param {ModuleLevel | null} mod
 */
function talentFields(t, b, mod) {
  const talents = upgradedTalents(t, b, mod), { cost = 0, respawn_time: respawn = 0, ...talentBb } = alwaysOnBb(talents);
  /** @type {[string, unknown[]][]} */
  const lists = [['fieldTalents', teamTalentsAt(t, b).field], ['rangeTalents', talents.map(rangePart).filter((p) => p !== null)],
    ['critTalents', talents.map(critPart).filter((p) => p !== null)], ['timedTalents', talents.map(timedPart).filter((p) => p !== null)],
    ['deployTalents', talents.map(deployPart).filter((p) => p !== null)]];
  return {
    cost, respawn,
    fields: { ...(Object.keys(talentBb).length ? { talentBb } : {}), ...Object.fromEntries(lists.filter(([, v]) => v.length > 0)) },
  };
}

/**
 * An operator at a training (干员-1…干员-3, 干员-6, 干员-7, 干员-9, 干员-11…干员-13) as @aue/sim reads it: its
 * attributes, the elite phase's range, its branch's trait (职业-7), the skill it brings at its level (技能-1), and its
 * talents' fields (talentFields). Throws for an elite phase it does not have, or a skill or module not unlocked yet.
 * @param {Training} t @param {Build} b @returns {OperatorDef}
 */
export function operatorAt(t, b) {
  const phase = t.phases[b.elite];
  if (!phase) throw new RangeError(`${t.name}: no elite phase ${b.elite}`);
  const slot = b.skill >= 0 ? t.skills[b.skill] : undefined;
  if (b.skill >= 0 && (!slot || slot.phase > b.elite)) throw new RangeError(`${t.name}: skill ${b.skill} is not unlocked at elite ${b.elite}`);
  const mod = moduleAt(t, b), s = statsAt(t, b, mod), level = slot ? slot.levels[clamp(b.skillLevel, 1, slot.levels.length) - 1] : null;
  const { cost, respawn, fields } = talentFields(t, b, mod);
  return withTrait({
    name: t.name, position: t.position, profession: t.profession, branch: t.branch, powers: t.powers, range: phase.range, traitBb: traitAt(t, b),
    maxHp: s.maxHp, atk: s.atk, def: s.def, res: s.res, cost: Math.max(0, s.cost + cost), blockCnt: s.blockCnt, baseAttackTime: s.baseAttackTime,
    respawnTime: Math.max(0, s.respawnTime + respawn), aspd: s.aspd, tauntLevel: s.tauntLevel, massLevel: s.massLevel,
    ...fields, ...(slot && level ? { skill: skillDefOf(slot.id, level) } : {}),
  });
}
